import { expect, test } from 'vitest'
import { atan2, cos, exp, hypot, log, pow, sin, tan } from '#src/math/dmath'

const FNS: Record<string, (...args: number[]) => number> = { sin, cos, tan, atan2, exp, log, pow, hypot }

/** Committed bit patterns, generated by the A0 S5 implementation (bit-identical in Node, Chromium, WebKit, Firefox). */
const GOLDEN: Array<[string, number[], string]> = [
  ['sin', [0.5], '3fdeaee8744b05f0'],
  ['cos', [0.5], '3fec1528065b7d50'],
  ['sin', [-1.25], 'bfee5e14fe11418c'],
  ['cos', [-1.25], '3fd42e3dd88bd952'],
  ['sin', [3], '3fc210386db6d55b'],
  ['cos', [3], 'bfefae04be85e5d2'],
  ['sin', [100.75], '3fcbd016b624497d'],
  ['cos', [100.75], '3fef3c45f03da266'],
  ['sin', [-999.9], 'bfe88805df2bfd23'],
  ['cos', [-999.9], '3fe48c3eaeb3a4cc'],
  ['sin', [1e-8], '3e45798ee2308c3a'],
  ['cos', [1e-8], '3ff0000000000000'],
  ['sin', [123456.789], 'bfeff50e60ab53f9'],
  ['cos', [123456.789], '3faa74d27c41b22a'],
  ['tan', [0.3], '3fd3cc2a44e29997'],
  ['tan', [-2], '40017af62e0950f7'],
  ['tan', [1.4], '401731086dc00a35'],
  ['atan2', [1, 1], '3fe921fb54442d18'],
  ['atan2', [1, -1], '4002d97c7f3321d2'],
  ['atan2', [-1, -1], 'c002d97c7f3321d2'],
  ['atan2', [0.5, 2], '3fcf5b75f92c80dd'],
  ['atan2', [-3, 0.25], 'bff7cd6f6dc59db4'],
  ['atan2', [7, -0.001], '3ff92291203036eb'],
  ['exp', [0], '3ff0000000000000'],
  ['exp', [1], '4005bf0a8b14576a'],
  ['exp', [-1], '3fd78b56362cef38'],
  ['exp', [10.5], '40e1bb7015e84d3b'],
  ['exp', [-20.25], '3e1b93de1e27ca3b'],
  ['exp', [700], '7f0d945df4f8ec8e'],
  ['exp', [-740], '0000000000000055'],
  ['log', [1], '0000000000000000'],
  ['log', [2], '3fe62e42fefa39ef'],
  ['log', [0.001], 'c01ba18a998fffa0'],
  ['log', [1e300], '4085963447f87fb5'],
  ['log', [5e-324], 'c0874385446d71c3'],
  ['log', [123.456], '401343774f3e2362'],
  ['pow', [2, 10], '4090000000000000'],
  ['pow', [2, 0.5], '3ff6a09e667f3bcc'],
  ['pow', [9.5, -3.25], '3f45c4fd2cc82f2f'],
  ['pow', [1.5, 2], '4002000000000000'],
  ['pow', [-2, 3], 'c020000000000000'],
  ['pow', [10, -2], '3f847ae147ae147b'],
  ['hypot', [3, 4], '4014000000000000'],
  ['hypot', [100000, 0.002], '40f86a0000000001'],
]

function bits(x: number): string {
  const v = new DataView(new ArrayBuffer(8))
  v.setFloat64(0, x)
  return v.getBigUint64(0).toString(16).padStart(16, '0')
}

test.each(GOLDEN)('%s(%j) has the committed bit pattern %s in every engine', (fn, args, expected) => {
  const f = FNS[fn]
  if (!f) throw new Error(`unknown function ${fn}`)
  expect(bits(f(...args))).toBe(expected)
})
